@layer properties;
:root, :host {
  --spacing: 0.25rem;
}
.translate-x-1 {
  --tw-translate-x: calc(var(--spacing) * 1);
  translate: var(--tw-translate-x) var(--tw-translate-y);
}
.before\:flex {
  &::before {
    content: var(--tw-content);
    display: flex;
  }
}
@property --tw-translate-x {
  syntax: "*";
  inherits: false;
  initial-value: 0;
}
@property --tw-translate-y {
  syntax: "*";
  inherits: false;
