@theme { --spacing: 0.25rem; --color-red-500: #f00; --breakpoint-md: 48rem; }
@tailwind utilities;
@custom-variant firefox (:-moz-any(&));
@custom-variant webkit (:-webkit-any(&, .x) > &);
.q { :-moz-any(&) b { color: red; } }

4.2.0.css:
.firefox\:underline {
  :-moz-any(&) {
    text-decoration-line: underline;
  }
}
.hover\:firefox\:flex {
  &:hover {
    @media (hover: hover) {
      :-moz-any(&) {
        display: flex;
      }
    }
  }
}
.webkit\:flex {
  :-webkit-any(&, .x) > & {
    display: flex;
  }
}
.q {
  :-moz-any(&) b {
    color: red;
  }
}

