:root, :host {
  --spacing: 0.25rem;
}
.a {
  margin: calc(var(--spacing) * 0);
  padding: calc(var(--spacing) * 1);
  gap: calc(var(--spacing) * 2);
}
.m-0 {
  margin: calc(var(--spacing) * 0);
}
.mt-\[--spacing\(0\)\] {
  margin-top: calc(var(--spacing) * 0);
}
.p-1 {
  padding: calc(var(--spacing) * 1);
}

