.bg-red-500\/\(--x\) {
  background-color: red;
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(in oklab, var(--color-red-500) var(--x), transparent);
  }
}
.bg-red-500\/\(-_x\) {
  background-color: red;
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(in oklab, var(--color-red-500) var(- x), transparent);
  }
}
.bg-red-500\/\(-x\) {
  background-color: red;
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(in oklab, var(--color-red-500) var(-x), transparent);
  }
}
.bg-red-500\/\(_-x\) {
  background-color: color-mix(in srgb, red var( -x), transparent);
  @supports (color: color-mix(in lab, red, red)) {
    background-color: color-mix(in oklab, var(--color-red-500) var( -x), transparent);
  }
}
